package com.bank.capacity.planner;

import com.bank.capacity.model.UserProfile;
import com.bank.capacity.model.Workload;
import java.util.logging.Logger;

// Converts "N users" + assumptions into the real drivers.
public class LoadEstimator {
    private static final Logger log = Logger.getLogger(LoadEstimator.class.getName());
    private static final long SECONDS_PER_DAY = 86_400L;

    private final int requestsPerActiveUserPerDay;
    private final int peakToAverageMultiplier;
    private final int bytesPerTransactionRow;
    private final int transactionsPerActiveUserPerDay;

    public LoadEstimator(int requestsPerActiveUserPerDay, int peakToAverageMultiplier,
                         int bytesPerTransactionRow, int transactionsPerActiveUserPerDay) {
        this.requestsPerActiveUserPerDay = requestsPerActiveUserPerDay;
        this.peakToAverageMultiplier = peakToAverageMultiplier;
        this.bytesPerTransactionRow = bytesPerTransactionRow;
        this.transactionsPerActiveUserPerDay = transactionsPerActiveUserPerDay;
    }

    public CapacityPlan estimate(UserProfile users, Workload workload) {
        // DRIVER 1: average rps derived from DAILY-ACTIVE users (not registered!).
        long totalDailyRequests = users.getDailyActive() * requestsPerActiveUserPerDay;
        long averageRps = totalDailyRequests / SECONDS_PER_DAY;

        // DRIVER 2: peak rps — what hardware must actually survive.
        long peakRps = averageRps * peakToAverageMultiplier;

        // DRIVER 3: read/write split drives caching vs sharding strategy.
        long peakReadRps = peakRps * workload.getReadPercent() / 100;
        long peakWriteRps = peakRps * workload.getWritePercent() / 100;

        // DRIVER 4: data size per year drives storage/sharding decisions.
        long txnPerYear = users.getDailyActive() * transactionsPerActiveUserPerDay * 365L;
        long dataSizeGbPerYear = (txnPerYear * bytesPerTransactionRow) / (1024L * 1024L * 1024L);

        log.info(() -> "CLARIFY: registered=" + users.getRegistered()
                + " dailyActive=" + users.getDailyActive()
                + " concurrentPeak=" + users.getConcurrentPeak());
        log.info(() -> "DERIVED peakRps=" + peakRps + " (read " + peakReadRps
                + "/write " + peakWriteRps + "), data/yr=" + dataSizeGbPerYear + "GB");
        if (workload.isStrongConsistency()) {
            log.warning("CONSISTENCY: strong required (balances) -> limit aggressive caching of balances");
        }
        return new CapacityPlan(averageRps, peakRps, peakReadRps, peakWriteRps,
                dataSizeGbPerYear, workload.isStrongConsistency(), workload.getLatencyP99TargetMs());
    }
}
