package com.bank.capacity;

import com.bank.capacity.model.UserProfile;
import com.bank.capacity.model.Workload;
import com.bank.capacity.planner.CapacityPlan;
import com.bank.capacity.planner.LoadEstimator;
import java.util.logging.*;

public class CapacityDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(CapacityDemo.class.getName());

        // Headline: "1 million users". NAIVE reading = 1,000,000 concurrent.
        log.severe("NAIVE: treating 1,000,000 as CONCURRENT -> massive over-build");

        // CLARIFIED: 1M registered → 10% DAU → 3% of DAU concurrent at peak.
        long registered = 1_000_000L;
        long dailyActive = (long) (registered * 0.10);          // 100,000
        long concurrentPeak = (long) (dailyActive * 0.03);      // 3,000
        UserProfile users = new UserProfile(registered, dailyActive, concurrentPeak);

        // Banking workload: read-heavy balance checks, strong consistency, tight latency.
        Workload workload = new Workload(90, true, 100);

        LoadEstimator estimator = new LoadEstimator(30, 8, 400, 5);
        CapacityPlan plan = estimator.estimate(users, workload);

        log.info("=== Engineering drivers that actually size the system ===");
        log.info("Average rps: " + plan.getAverageRps());
        log.info("Peak rps: " + plan.getPeakRps()
                + " (reads " + plan.getPeakReadRps() + ", writes " + plan.getPeakWriteRps() + ")");
        log.info("Data growth: ~" + plan.getDataSizeGbPerYear() + " GB/year");
        log.info("Strong consistency needed: " + plan.needsStrongConsistency());
        log.info("Latency p99 target: " + plan.getLatencyP99TargetMs() + " ms");
        log.info("CONCLUSION: size for ~" + plan.getPeakRps()
                + " peak rps, NOT for 1,000,000 concurrent.");
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
